:root {
  --bg: #1a1a2e;
  --bg2: #111122;
  --panel: #171a2b;
  --panel2: #1f2338;
  --line: #2b3050;
  --text: #e6eaf7;
  --muted: #9aa3c7;
  --blue: #2962ff;
  --teal: #00bfa5;
  --green: #22c55e;
  --red: #f7525f;
  --yellow: #eab308;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: Inter, "DM Sans", system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
  background: linear-gradient(180deg, #0f0f1a 0%, var(--bg) 100%);
  color: var(--text);
}
a { color: inherit; text-decoration: none; }
.container { width: min(1400px, 96vw); margin: 0 auto; }
.nav {
  position: sticky; top: 0; z-index: 50;
  background: rgba(12,13,22,0.9); backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--line);
}
.nav-inner { display: flex; align-items: center; gap: 20px; padding: 12px 0; }
.logo { font-weight: 800; color: #fff; letter-spacing: .4px; }
.logo span { color: var(--blue); }
.nav-links { display: flex; gap: 14px; flex-wrap: wrap; }
.nav-links a { color: var(--muted); padding: 8px 10px; border-radius: 8px; }
.nav-links a.active, .nav-links a:hover { color: #fff; background: #1e2340; }
.btn {
  border: 1px solid #3950b6; background: var(--blue); color: #fff;
  padding: 9px 14px; border-radius: 8px; font-weight: 600; cursor: pointer;
}
.btn.secondary { background: transparent; border-color: var(--line); color: var(--text); }
.spacer { flex: 1; }
.hero { padding: 26px 0 14px; }
.hero h1 { font-size: 2rem; margin: 0 0 10px; line-height: 1.2; }
.hero p { color: var(--muted); margin: 0 0 16px; max-width: 900px; }
.grid { display: grid; gap: 14px; }
.g-2 { grid-template-columns: 2fr 1fr; }
.g-3 { grid-template-columns: repeat(3, minmax(0,1fr)); }
.g-4 { grid-template-columns: repeat(4, minmax(0,1fr)); }
.panel { background: linear-gradient(180deg, var(--panel), var(--panel2)); border: 1px solid var(--line); border-radius: 12px; }
.panel h2 { margin: 0; font-size: 1rem; }
.panel-head { display:flex; justify-content:space-between; align-items:center; padding: 10px 12px; border-bottom: 1px solid var(--line); }
.panel-body { padding: 10px 12px; }
.row { display:flex; align-items:center; justify-content:space-between; gap:10px; padding:8px 0; border-bottom:1px solid rgba(154,163,199,.12); }
.row:last-child { border-bottom: 0; }
.small { font-size: .82rem; color: var(--muted); }
.badge { font-size: .78rem; padding: 3px 8px; border-radius: 999px; font-weight:700; }
.up { color: var(--green); }
.down { color: var(--red); }
.badge.up { background: rgba(34,197,94,.15); }
.badge.down { background: rgba(247,82,95,.15); }
.tabbar { display:flex; flex-wrap:wrap; gap:8px; }
.tab { border:1px solid var(--line); background:#14182d; color:var(--muted); padding:7px 10px; border-radius:8px; cursor:pointer; font-size:.82rem; }
.tab.active { color:#fff; border-color:#4963cc; background:#1a234a; }
.table { width:100%; border-collapse: collapse; font-size:.86rem; }
.table th,.table td { text-align:left; padding:8px 6px; border-bottom: 1px solid rgba(154,163,199,.14); }
.table th { color: var(--muted); font-weight:600; font-size:.78rem; text-transform: uppercase; letter-spacing:.03em; }
.footer { margin: 24px 0 30px; padding: 16px 0; border-top:1px solid var(--line); color: var(--muted); font-size:.85rem; }
.market-strip { display:grid; grid-template-columns: repeat(6,minmax(0,1fr)); gap:8px; }
.mini { background:#151a31; border:1px solid var(--line); border-radius:10px; padding:8px; }
.spark { height:36px; width:100%; }
.terminal { display:grid; grid-template-columns: 290px 1fr 360px; gap:10px; min-height: 700px; }
.watch-cat { border:1px solid var(--line); border-radius:8px; margin-bottom:8px; overflow:hidden; }
.watch-head { background:#13182d; padding:8px 10px; cursor:pointer; display:flex; justify-content:space-between; }
.watch-items { display:none; padding:0 8px 8px; }
.watch-cat.open .watch-items { display:block; }
.watch-item { display:grid; grid-template-columns: 1fr auto auto; gap:8px; padding:6px 2px; font-size:.83rem; border-bottom:1px solid rgba(154,163,199,.12); }
.chart-box { border:1px solid var(--line); border-radius:10px; overflow:hidden; }
.chart-toolbar { display:flex; justify-content:space-between; padding:8px; border-bottom:1px solid var(--line); background:#101426; }
.candle-wrap { height:430px; background: radial-gradient(circle at 20% 0%, #1f2750 0%, #0d1120 55%); padding:14px; }
.candle-svg { width:100%; height:100%; }
.kpi { display:grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap:8px; }
.kpi .mini { padding:10px; }
.idea-card { border:1px solid var(--line); border-radius:10px; padding:10px; background:#12162b; }
.broker { display:grid; grid-template-columns: 1.3fr .8fr .9fr .7fr; gap:10px; align-items:center; padding:10px; border-bottom:1px solid rgba(154,163,199,.15); }
@media (max-width: 1100px) {
  .g-2,.terminal { grid-template-columns: 1fr; }
  .market-strip { grid-template-columns: repeat(2,minmax(0,1fr)); }
  .g-3,.g-4 { grid-template-columns: 1fr; }
}
EOF

cat > /app/output/app.js << 'EOF'
const $ = (s, p=document) => p.querySelector(s);
const $$ = (s, p=document) => [...p.querySelectorAll(s)];

function setupTabs(scope=document){
  $$('.tabbar[data-tabs]', scope).forEach(tabbar=>{
    const key = tabbar.dataset.tabs;
    const tabs = $$('.tab', tabbar);
    const pages = $$(`[data-tab-content="${key}"]`, scope);
    tabs.forEach(tab=>tab.addEventListener('click', ()=>{
      tabs.forEach(t=>t.classList.remove('active'));
      tab.classList.add('active');
      const val = tab.dataset.tab;
      pages.forEach(p=>p.style.display = p.dataset.value===val ? '' : 'none');
    }));
    const active = $('.tab.active', tabbar) || tabs[0];
    if (active) active.click();
  });
}

function setupWatchAccordion(){
  $$('.watch-head').forEach(head=>{
    head.addEventListener('click', ()=> head.parentElement.classList.toggle('open'));
  });
}

function setupVideoToggle(){
  const t = $('#videoOnly'); if(!t) return;
  t.addEventListener('change', ()=>{
    $$('.idea-card').forEach(card=>{
      const isVideo = card.dataset.video === 'true';
      card.style.display = (!t.checked || isVideo) ? '' : 'none';
    });
  });
}

function drawSparks(){
  $$('.spark').forEach(svg=>{
    const up = svg.dataset.trend !== 'down';
    const pts = up ? '2,30 22,26 42,24 62,18 82,20 102,14 122,8' : '2,8 22,11 42,14 62,18 82,19 102,25 122,29';
    svg.innerHTML = `<polyline fill="none" stroke="${up?'#22c55e':'#f7525f'}" stroke-width="2" points="${pts}" />`;
  });
}

function drawCandles(){
  const svg = $('#candles'); if(!svg) return;
  const w = svg.clientWidth || 820; const h = svg.clientHeight || 360;
  let x = 16; let out='';
  for(let i=0;i<60;i++){
    const open = 140 + Math.sin(i/6)*38 + (Math.random()*18);
    const close = open + (Math.random()*24-12);
    const high = Math.max(open, close) + (Math.random()*12);
    const low = Math.min(open, close) - (Math.random()*12);
    const y = v => h - (v/250)*h;
    const up = close >= open;
    out += `<line x1="${x+4}" x2="${x+4}" y1="${y(high)}" y2="${y(low)}" stroke="${up?'#22c55e':'#f7525f'}"/>`;
    out += `<rect x="${x}" y="${y(Math.max(open,close))}" width="8" height="${Math.max(2, Math.abs(y(open)-y(close)))}" fill="${up?'#22c55e':'#f7525f'}"/>`;
    x += 12;
  }
  svg.innerHTML = out;
}

document.addEventListener('DOMContentLoaded', ()=>{
  setupTabs();
  setupWatchAccordion();
  setupVideoToggle();
  drawSparks();
  drawCandles();
});
EOF

